const formItem = $('Upload form').first();
const form = formItem.json;
const key = Object.keys(form).find(k => k.trim().toLowerCase() === 'dashboard name');
const typed = key ? String(form[key] || '').trim() : '';
const fileBase = String(formItem.binary?.data?.fileName || '').replace(/\.csv$/i, '');
const name = typed || fileBase || 'dataset';

const rows = $input.all().map(i => i.json);
if (!rows.length) throw new Error('CSV is empty');

const table = 't_' + name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

const clean = c => c.toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '') || 'col';
const cols = Object.keys(rows[0]);
const seen = {};
const names = cols.map(c => {
  const n = clean(c);
  seen[n] = (seen[n] || 0) + 1;
  return seen[n] > 1 ? `${n}_${seen[n]}` : n;
});

const typeOf = c => {
  const vals = rows.map(r => r[c]).filter(v => v !== '' && v != null);
  if (!vals.length) return 'TEXT';
  if (vals.every(v => /^-?(0|[1-9]\d*)$/.test(String(v)))) return 'BIGINT';
  if (vals.every(v => !isNaN(Number(v)))) return 'DOUBLE PRECISION';
  if (vals.every(v => /^\d{4}-\d{2}-\d{2}/.test(String(v)) && !isNaN(Date.parse(v)))) return 'TIMESTAMP';
  return 'TEXT';
};
const types = cols.map(typeOf);

const lit = v => (v === '' || v == null) ? 'NULL' : `'${String(v).replace(/'/g, "''")}'`;
const out = [
  { json: { sql: `DROP TABLE IF EXISTS ${table}`, table, rowCount: rows.length } },
  { json: { sql: `CREATE TABLE ${table} (${names.map((n, i) => `"${n}" ${types[i]}`).join(', ')})` } },
];
for (let i = 0; i < rows.length; i += 500) {
  const values = rows.slice(i, i + 500)
    .map(r => '(' + cols.map(c => lit(r[c])).join(',') + ')').join(',');
  out.push({ json: { sql: `INSERT INTO ${table} VALUES ${values}` } });
}
return out;
